(function ($) {

    // Fixed clone function
    (function (original) {
        jQuery.fn.clone = function () {
            var result           = original.apply(this, arguments),
                my_textareas     = this.find('textarea').add(this.filter('textarea')),
                result_textareas = result.find('textarea').add(result.filter('textarea')),
                my_selects       = this.find('select').add(this.filter('select')),
                result_selects   = result.find('select').add(result.filter('select'));

            for (var i = 0, l = my_textareas.length; i < l; ++i) $(result_textareas[i]).val($(my_textareas[i]).val());
            for (var i = 0, l = my_selects.length;   i < l; ++i) {
                for (var j = 0, m = my_selects[i].options.length; j < m; ++j) {
                    if (my_selects[i].options[j].selected === true) {
                        result_selects[i].options[j].selected = true;
                    }
                }
            }
            return result;
        };
    }) (jQuery.fn.clone);

    // Prevent scroll
    // left: 37, up: 38, right: 39, down: 40,
    // spacebar: 32, pageup: 33, pagedown: 34, end: 35, home: 36
    var keys = {37: 1, 38: 1, 39: 1, 40: 1};

    function preventDefault(e) {
        e = e || window.event;
        if (e.preventDefault)
            e.preventDefault();
        e.returnValue = false;
    }

    function preventDefaultForScrollKeys(e) {
        if (keys[e.keyCode]) {
            preventDefault(e);
            return false;
        }
    }

    function disableScroll() {
        if (window.addEventListener) // older FF
            window.addEventListener('DOMMouseScroll', preventDefault, false);
        window.onwheel = preventDefault; // modern standard
        window.onmousewheel = document.onmousewheel = preventDefault; // older browsers, IE
        window.ontouchmove  = preventDefault; // mobile
        document.onkeydown  = preventDefaultForScrollKeys;
    }

    function enableScroll() {
        if (window.removeEventListener)
            window.removeEventListener('DOMMouseScroll', preventDefault, false);
        window.onmousewheel = document.onmousewheel = null;
        window.onwheel = null;
        window.ontouchmove = null;
        document.onkeydown = null;
    }

    // Parallax
    var parallax = function() {
        $(window).load(function() {
            $(window).stellar();
        });
    };

    // Burger Menu
    var burgerMenu = function() {
        $('body').on('click', '.js-nav-toggle', function(event) {
            event.preventDefault();

            if ( $('#navbar').is(':visible') ) {
                $(this).removeClass('active');
            } else {
                $(this).addClass('active');
            }
        });
    };

    var burgerMenuContent = function() {
        $('body').on('click', '.js-content-nav-toggle', function(event) {
            event.preventDefault();

            if ( $('#navbar-content').is(':visible') ) {
                $(this).removeClass('active');
            } else {
                $(this).addClass('active');
            }
        });
    };

    // Window Scroll
    var windowScroll = function() {
        var lastScrollTop = 0;

        $(window).scroll(function(event) {
            var header = $('#header'),
                scrlTop = $(this).scrollTop();

            if (scrlTop > 800 && scrlTop <= 2000) {
                header.addClass('navbar-fixed-top menu-animated slideInDown');
            }
            else if (scrlTop <= 800) {
                if (header.hasClass('navbar-fixed-top')) {
                    header.addClass('navbar-fixed-top menu-animated slideOutUp');

                    setTimeout(function() {
                        header.removeClass('navbar-fixed-top menu-animated slideInDown slideOutUp');
                    }, 100);
                }
            }
        });
    };

    // Scroll to form
    var scrollToForm = function() {
        $('.scroll-to-form').on('click', function(event) {
            event.preventDefault();
            disableScroll();

            $('html, body').animate({
                scrollTop: $('.contract').offset().top - 20
            }, 800, enableScroll);

            return false;
        });
    };

    // Scroll to content
    var scrollToContent = function() {
        if ($('body').hasClass('scroll-to-content')) {
            disableScroll();

            setTimeout(function() {
                $('html, body').animate({
                    scrollTop: $('#content').offset().top - 25
                }, 800, enableScroll);
            }, 1000);
        }
    };

    // Go to top
    var goToTop = function() {
        $('.js-go-top').on('click', function(event) {
            event.preventDefault();
            disableScroll();

            $('html, body').animate({
                scrollTop: $('html').offset().top
            }, 800, enableScroll);

            return false;
        });
    };

    // Custom select
    var customSelect = function() {
        $(window).load(function() {
            if ($('body').hasClass('homepage')) {
                $('.form-select select').niceSelect();
            }
        });
    };

    // Select person type
    var selectPerson = function() {
        $( '.contract .person-select' ).change(function() {
            var showClass = '.' + $( this ).val();
            var parent = $( this ).parents('.form-debtor, .form-creditor, .form-guarantor');
            parent.find(showClass).show();
            parent.find('.fon, .fop, .po').not(showClass).hide();
        });
    };

    // Radio select
    var radioSelect = function() {
        $( '.contract .form-radio input' ).change(function() {
            var showClass = '.' + $( this ).val();
            var parent = $( this ).parent().parent().parent();

            parent.children(showClass).show();
            parent.children('.hide-this').not(showClass).hide();
        });
    };

    // Debtors variable
    var debtors_counter = 0;

    // Add debtor
    var addDebtor = function() {
        $('.add-debtor').click(function() {
            var $elem = $('.form-debtor:first').clone(true);
            $elem.find('input:text').val('');
            $elem.addClass('debtor-' + debtors_counter);

            debtors_counter++;
            $('input[name="d_counter"]').val(debtors_counter);

            $('.remove-debtor').removeClass('hidden');
            $('#form-contract-d_counter').val(debtors_counter.toString());
            $('#form-contract-d_counter').attr('value',debtors_counter.toString());

            $elem.find( 'input' ).each(function(){
                var name = $(this).attr('name');
                $(this).attr('name', name + debtors_counter);
                var id = $(this).attr('id');
                $(this).attr('id', id + debtors_counter);
            });

            $elem.find( 'select' ).each(function(){
                var name = $(this).attr('name');
                $(this).attr('name', name + debtors_counter);
                var id = $(this).attr('id');
                $(this).attr('id', id + debtors_counter);
            });

            $('.form-buttons').before($elem);
        });
    };

    // Remove debtor
    var removeDebtor = function() {
        $('.remove-debtor').click(function() {
            debtors_counter--;
            $('input[name="d_counter"]').val(debtors_counter);

            $( ".debtor-" + debtors_counter ).remove();
            $('#form-contract-d_counter').val(debtors_counter.toString());
            $('#form-contract-d_counter').attr('value',debtors_counter.toString())

            if (debtors_counter == 0) {
                $('.remove-debtor').addClass('hidden');
            }
        });
    };

    // Currency select
    var currencySelect = function() {
        $('.contract select.currency').change(function () {
            var currencyOther = $(this).parents('.form-currency').children(':first');
            var selected = $(this).find('option:selected').val();

            if (selected == 'other_currency') {
                currencyOther.removeClass('hidden');
            } else {
                currencyOther.addClass('hidden');
            }
        });
    };

    var currencySelectOther = function() {
        $('.contract .currency.other').keyup(function() {
            var otherOption = $( this ).parents('.form-currency').find( 'option.other' );
            otherOption.val( $( this ).val() );
        });
    };

    // Contract submit
    var contractSubmit = function() {
        $('.contract form').first().submit(function(){
            var priceElems = $( '.contract select.currency' );

            priceElems.each(function(){
                var prev_input = $( this ).parent().parent().prev('.form-cell').find( 'input' );
               // var new_name = prev_input.attr( 'name' );
//
              //  if( new_name[new_name.length-1] == ']' ) {
                   // new_name = 'currency_select[' + new_name.substr(0, new_name.length-2) + '][]';
              //  }	else {
                   // new_name = 'currency_select[' + new_name + ']';
              //  }

                //$( this ).attr( 'name', new_name );
            });
        });
    };

    // reCaptcha fix
    var recaptchaFix = function() {
        var width = $('.g-recaptcha').parent().width();

        if (width < 302) {
            var scale = width / 302;
            $('.g-recaptcha').css('transform', 'scale(' + scale + ')');
            $('.g-recaptcha').css('-webkit-transform', 'scale(' + scale + ')');
            $('.g-recaptcha').css('transform-origin', '0 0');
            $('.g-recaptcha').css('-webkit-transform-origin', '0 0');
        }
    };

    // Header animation
    var headerAnimate = function() {
        var header = $('#home');

        if (header.length > 0) {
            header.waypoint(function(direction) {
                if(direction === 'down' && !$(this.element).hasClass('animated')) {
                    setTimeout(function() {
                        header.find('.to-animate').each(function(k) {
                            var el = $(this);

                            setTimeout(function() {
                                el.addClass('fadeInUp animated');
                            }, k * 200);
                        });
                    }, 400);

                    $(this.element).addClass('animated');
                }
            }, { offset: '100%' });
        }
    };

    // Content animation
    var contentAnimate = function() {
        var content = $('.content, .contract');
        var container = $('#content');

        if (content.length > 0) {
            content.waypoint(function(direction) {
                if(direction === 'down' && !$(this.element).hasClass('animated')) {
                    setTimeout(function() {

                        container.addClass('fadeInUp animated');
                        content.addClass('fadeInUp animated');
                        content.find('.to-animate').each(function(k) {
                            var el = $(this);

                            setTimeout(function() {
                                el.addClass('fadeIn animated');
                            }, k * 200);
                        });
                    }, 400);

                    $(this.element).addClass('animated');
                }
            }, { offset: '100%' });
        }
    };

    // Footer animation
    var footerAnimate = function() {
        var footer = $('#footer');

        if (footer.length > 0) {
            footer.waypoint(function(direction) {
                if(direction === 'down' && !$(this.element).hasClass('animated')) {
                    setTimeout(function() {
                        footer.find('.to-animate').each(function(k) {
                            var el = $(this);

                            setTimeout(function() {
                                el.addClass('fadeIn animated');
                            }, k * 200);
                        });
                    }, 400);

                    $(this.element).addClass('animated');
                }
            }, { offset: '100%' });
        }
    };

    // Document ready
    $(function() {
        parallax();
        burgerMenu();
        burgerMenuContent();
        windowScroll();
        scrollToForm();
        goToTop();
        customSelect();
        selectPerson();
        radioSelect();
        addDebtor();
        removeDebtor();
        currencySelect();
        currencySelectOther();
        contractSubmit();
        recaptchaFix();

        // Animations
        Pace.on('done', function() {
            //preloader();
            scrollToContent();
            headerAnimate();
            contentAnimate();
            footerAnimate();
        });
    });
})(jQuery);
